const escapeXml = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// base64 → Uint8Array (브라우저 atob 사용)
const b64ToBytes = (b64) => {
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
};

// 자리표시자 런 전체(<hp:run charPrIDRef="빨강"><hp:t>...</hp:t>)를
// 검정 charPr + 채운 텍스트로 교체한다.
const fillRun = (xml, redId, blackId, placeholder, value) =>
  xml.split(
    '<hp:run charPrIDRef="' + redId + '"><hp:t>' + placeholder + '</hp:t>'
  ).join(
    '<hp:run charPrIDRef="' + blackId + '"><hp:t>' + value + '</hp:t>'
  );

// section0.xml 의 자리표시자 런을 폼 값으로 치환 (글자색은 검정으로)
const fillSection = (xml, data) => {
  let out = xml;
  const event = data.eventName ? escapeXml(data.eventName) : null;
  const gradeText =
    data.grades && data.grades.length > 0 ? escapeXml(data.grades.join(', ')) : null;

  // 1) 행사명: 제목(charPr 34) + 신청서 제목(charPr 11) 두 곳
  if (event) {
    out = fillRun(out, 11, 49, '◯◯◯◯◯◯◯', event);
    out = fillRun(out, 34, 52, '◯◯◯◯◯◯◯', event);
  }
  // 2) 대상 학년: charPr 24, <hp:t>◯</hp:t>
  if (gradeText) {
    out = fillRun(out, 24, 50, '◯', gradeText);
  }
  // 3) 일시: 라벨의 연도 오타(2025) 교정 + 값 placeholder(charPr 24) 치환
  if (data.dateTimeStr) {
    out = out.replace('<hp:t>2. 일시: 2025. </hp:t>', '<hp:t>2. 일시: </hp:t>');
    out = fillRun(
      out,
      24,
      50,
      '◯◯. ◯◯. (◯) ◯◯:◯◯~◯◯:◯◯',
      escapeXml(data.dateTimeStr)
    );
  }
  // 4) 장소: charPr 27, <hp:t>체험 장소 입력</hp:t>
  if (data.location) {
    out = fillRun(out, 27, 51, '체험 장소 입력', escapeXml(data.location));
  }
  // 5) 이동방법: charPr 28, <hp:t>교육청 제공버스/도보</hp:t>
  if (data.transport) {
    out = fillRun(out, 28, 53, '교육청 제공버스/도보', escapeXml(data.transport));
  }
  return out;
};

// 폼 데이터로 원본 양식을 채운 .hwpx Blob 생성
export const buildGtongsinBlob = async (data) => {
  const zip = new JSZip();
  for (const part of PARTS) {
    const opts = part.name === 'mimetype' ? { compression: 'STORE' } : undefined;
    if (part.type === 'text') {
      zip.file(part.name, fillSection(part.data, data), opts);
    } else {
      zip.file(part.name, b64ToBytes(part.data), opts);
    }
  }
  return zip.generateAsync({ type: 'blob', mimeType: 'application/hwp+zip' });
};
